<script setup>import{ref}from'vue';import{api}from'../api';import{IonPage,IonContent,IonButton}from'@ionic/vue';const code=ref('WMS|DELIVERY|DEL-1001|PICKUP|v1'),result=ref(null);async function go(){try{result.value=(await api.post('/scans',{code:code.value,method:'QR_MOBILE'})).data}catch(e){result.value=e.response?.data}}</script><template><ion-page><ion-content><div class="mob-hero"><small>TRACEABILITY</small><h1>Scan workflow</h1><p>QR today; the same event stream accepts RFID reader events.</p></div><div class="scanbox"><label>QR payload</label><input v-model="code"/><ion-button expand="block" @click="go">Process scan</ion-button><div class="note">For browser testing, paste the QR payload. For a packaged Android/iOS build, connect a Capacitor barcode-scanner plugin to feed the same API.</div><div v-if="result" class="result" style="margin-top:12px">{{JSON.stringify(result,null,2)}}</div></div></ion-content></ion-page></template>
